// static
bool StructTraits<::side_panel::mojom::ImageQuery::DataView, ::side_panel::mojom::ImageQueryPtr>::Read(
    ::side_panel::mojom::ImageQuery::DataView input,
    ::side_panel::mojom::ImageQueryPtr* output) {
  bool success = true;
  ::side_panel::mojom::ImageQueryPtr result(::side_panel::mojom::ImageQuery::New());
  
      if (success && !input.ReadUploadUrl(&result->upload_url))
        success = false;
      if (success && !input.ReadImageUrl(&result->image_url))
        success = false;
      if (success && !input.ReadContentType(&result->content_type))
        success = false;
      if (success && !input.ReadImageBytes(&result->image_bytes))
        success = false;
      if (success)
        result->height = input.height();
      if (success)
        result->width = input.width();
      if (success)
        result->downscaled_height = input.downscaled_height();
      if (success)
        result->downscaled_width = input.downscaled_width();
  *output = std::move(result);
  return success;
}


